'use strict';
let edgeChecked=0,edgeBusy=false;
function predictionExecutionHTML(q){
 const ask=q.ask,bid=q.bid,valid=Number.isFinite(ask)&&Number.isFinite(bid)&&ask>0&&bid>=0&&bid<=ask;
 if(!valid)return '<p>Execution check unavailable: a valid two-sided order book is required.</p>';
 const shares=q.book.asks.filter(x=>Number(x.price)===ask).reduce((s,x)=>s+Number(x.size),0),friction=(ask-bid)/ask*100;
 return `<section class="decision-check"><b>Before entering ${esc(q.outcome.label)}</b><span>Buy now / immediate sell difference: ${friction.toFixed(2)}% before fees.</span><span>At the best ask: ${shares.toLocaleString()} shares · about $${(shares*ask).toFixed(2)} available. Larger orders can cost more.</span><span>Holding to resolution needs a success probability above ${(ask*100).toFixed(1)}% before fees to break even.</span><small>${q.market.feesEnabled?'Fees apply and raise the break-even level.':'Verify the contract’s fee settings.'} poor has not established a calibrated probability advantage for this contract.</small></section>`;
}
function edgeMetric(n,suffix='%'){return Number.isFinite(n)?(n>0?'+':'')+n.toFixed(2)+suffix:'—'}
function decisionPlanHTML(a){const p=a.tradePlan;if(!p)return '';return `<section class="decision-check"><b>${p.direction==='long'?'Bullish thesis':'Watch only'} · ${esc(p.symbol)}</b><span><b>Entry condition:</b> ${esc(p.entryTrigger)}</span><span><b>Catalyst:</b> ${esc(p.catalyst)}</span><span><b>Exit rule:</b> ${esc(p.exitRule)}</span><small>Conditional research plan; entry has not been confirmed or executed.</small></section>`}
function edgeScoreHTML(d,compact=false){const s=d.summary||{},metrics=[['Completed theses',String(s.completed||0)],['Average after costs',edgeMetric(s.meanNet)],['vs S&P 500',edgeMetric(s.meanExcess,' pp')],['Win rate',s.winRate==null?'—':s.winRate.toFixed(0)+'%']];
 return `<div class="home-heading"><h2>Does poor have an edge?</h2><b class="edge-status">Not established</b></div><div class="edge-metrics">${metrics.map(([label,value])=>`<span>${label}<b>${value}</b></span>`).join('')}</div><p class="home-caption">${d.registered} registered · ${s.winners||0} wins / ${s.losers||0} losses / ${s.flat||0} flat · ${d.rows.filter(r=>r.state!=='Completed'&&r.state!=='Watch only').length} pending or missing data · ${d.legacy} legacy articles excluded${d.omitted?' · '+d.omitted+' beyond current coverage limit':''}. Updated ${stamp(d.updatedAt)}.</p>${compact?'<button data-view="daily">Inspect results & method →</button>':`<p class="home-caption">Cost stress: ${edgeMetric(s.costStress)} average · Worst individual closing drawdown: ${edgeMetric(s.worstDrawdown)}. These are research outcomes, not account profits.</p><details><summary>Fixed measurement method</summary><p>${esc(d.method)}</p><p>A positive average alone does not establish a persistent edge. Sample size, correlated ideas, changing market conditions and independently verified executions still matter.</p></details><details><summary>Every registered thesis · ${d.rows.length}</summary><div class="edge-results">${d.rows.map(r=>`<article><button data-ticker="${esc(r.symbol)}">${esc(r.symbol)}</button><b>${esc(r.title)}</b><small>${stamp(r.publishedAt)} · ${esc(r.state)} · Review: ${esc(r.lastReview)}</small>${r.state==='Completed'?`<span>${edgeMetric(r.netReturn)} after costs · ${edgeMetric(r.excess,' pp')} vs S&P 500</span><small>Entry ${date(r.entry)} at $${r.entryPrice.toFixed(2)} → ${date(r.end)} at $${r.exitPrice.toFixed(2)}</small>`:''}</article>`).join('')||'<p>No prospective theses registered yet. Old winners will not be backfilled into this record.</p>'}</div></details>`}`;
}
async function refreshEdgeScore(force=false){if(edgeBusy||!force&&Date.now()-edgeChecked<900000)return;edgeBusy=true;try{const response=await getLiveJSON('/api/research/scorecard');if(!response.value)throw Error();const d=response.value;for(const [id,compact]of [['homeEdgeScore',true],['researchEdgeScore',false]]){const el=document.getElementById(id);if(el){el.innerHTML=edgeScoreHTML(d,compact)+(response.stale?'<p>Saved scorecard · refresh failed</p>':'');el.dataset.loaded='true'}}edgeChecked=Date.now()}catch{for(const id of ['homeEdgeScore','researchEdgeScore']){const el=document.getElementById(id);if(el&&!el.dataset.loaded)el.textContent='Performance record unavailable. No trading edge is assumed.'}}finally{edgeBusy=false}}
if(typeof window!=='undefined'){refreshEdgeScore();document.addEventListener('click',e=>{if(e.target.closest('#dailyRefresh,#refreshHomeSetups'))refreshEdgeScore(true)});setInterval(()=>{if(!document.hidden)refreshEdgeScore()},900000)}
